        assert_eq!(session_warm_up(eager, 2).await.expect("eager"), 0);
        assert_eq!(session_warm_up(9_999_999, 2).await.expect("unknown"), 0);

        close_session(eager);
        close_session(lazy);
        std::fs::remove_dir_all(&dir).expect("remove temp dir");
    }
